// Shared by audio, custom export and song projects. The browser cannot confirm that
// a file reached disk, so its result deliberately says "Download requested".
async function saveDownload(filename, data) {
  let downloads = null;
  try { if (window.claude && window.claude.use) downloads = await window.claude.use("downloads"); } catch (_) { /* use the browser */ }
  if (downloads && typeof downloads.save === "function") {
    await downloads.save({ filename, data }); // a declined host save stays cancelled
    return "Saved";
  }
  const blob = data instanceof Blob ? data : new Blob([data], { type: /\.wav$/i.test(filename)?"audio/wav":/\.json$/i.test(filename)?"application/json":/\.txt$/i.test(filename)?"text/plain":"application/zip" });
  const url = URL.createObjectURL(blob), link = document.createElement("a");
  link.href = url; link.download = filename; link.textContent = "Download " + filename;
  link.style.cssText = "display:block;padding:12px;overflow-wrap:anywhere";
  let box = document.getElementById("browserDownloads");
  if (!box) {
    box = document.createElement("section"); box.id = "browserDownloads"; box.setAttribute("aria-label", "Prepared downloads");
    box.style.cssText = "position:fixed;bottom:12px;right:12px;max-width:90vw;max-height:35vh;overflow:auto;background:#182b25;border:1px solid #8de4b7;border-radius:12px;z-index:10000;padding:10px";
    const note=document.createElement("div"); note.textContent="If saving did not start, tap the file link. Your browser may ask where to save it."; box.append(note);
    const close=document.createElement("button"); close.textContent="Close downloads";
    close.onclick=()=>{for(const a of box.querySelectorAll("a"))URL.revokeObjectURL(a.href);box.remove();};box.append(close);
    document.body.append(box);
  }
  box.classList.remove("dl-folded"); box.append(link); link.click();
  // 0.23.1: the box is a small toast; after a few seconds it folds to a tiny "Downloads" chip (tap to open again)
  box.classList.remove("dl-folded"); clearTimeout(box._fold); box._fold=setTimeout(()=>box.classList.add("dl-folded"),6000);
  if(!box._chip){ box._chip=true; box.addEventListener("click",e=>{ if(e.isTrusted&&box.classList.contains("dl-folded")){ e.preventDefault(); box.classList.remove("dl-folded"); clearTimeout(box._fold); box._fold=setTimeout(()=>box.classList.add("dl-folded"),8000);} },true); }
  { const old=[...box.querySelectorAll("a")].slice(0,-2); for(const a of old){ setTimeout(()=>URL.revokeObjectURL(a.href),60000); a.remove(); } } // 0.18.2: only the 2 newest links, so the box stays small
  return "Download requested";
}

