$("protect").onchange = () => setP("protectConsonants", $("protect").checked ? 1 : 0);
$("protectExpression").onchange=()=>setP("protectExpression",$("protectExpression").checked?1:0);
$("keepInTune").onchange = () => setP("keepInTune", $("keepInTune").checked ? 1 : 0);
$("followSinging").onchange = () => setP("followSinging", $("followSinging").checked ? 1 : 0);
