  const hard = P.style === 2;
  tuneKnobs.amount.setQuiet(round(P.amount * 100)); tuneKnobs.drift.setQuiet(round(P.drift * 100)); tuneKnobs.speed.setQuiet(round(P.speed)); tuneKnobs.expression.setQuiet(round(P.expression * 100));
