  $("preserve").checked = P.preserve > .5; $("snapKey").checked = P.snapKey > .5; $("protect").checked = P.protectConsonants > .5; $("matchVol").checked = S.match;
  $("protectExpression").checked=P.protectExpression>.5; $("keepInTune").checked = P.keepInTune > .5; $("followSinging").checked = P.followSinging > .5;
  for (const b of document.querySelectorAll("#styleSeg button")) b.setAttribute("aria-pressed", +b.dataset.style === P.style);
  for (const b of document.querySelectorAll("#rangeSeg button")) b.setAttribute("aria-pressed", +b.dataset.range === P.vocalRange);
  $("rangeInfo").textContent = P.vocalRange === 4 ? "Learned: " + Math.round(P.rangeLow) + "–" + Math.round(P.rangeHigh) + " Hz" : ["All notes from 60 to 1100 Hz (safest).", "Low voice: 60–400 Hz.", "Mid voice: 80–750 Hz.", "High voice: 140–1100 Hz."][P.vocalRange] || "";
