    $("keyInfo").textContent = (same ? "Detected: " : "Sounds like: ") + SHORT[g.key] + (g.scale === 1 ? " major" : " minor") + (g.confidence < 0.3 ? " (not sure)" : "");
    $("useKey").hidden = same;
