    const v = r.snrDb >= 50 ? "Very clean" : r.snrDb >= 38 ? "Clean" : r.snrDb >= 26 ? "Some background noise" : r.snrDb >= 16 ? "Noisy" : "Very noisy";
    $("noiseVerdict").textContent = v + " (your voice is " + Math.round(r.snrDb) + " dB above it)";
