  if (id === "style") return ["Natural", "Polished", "Hard Tune"][Math.round(v)] || v;
  if (["amount", "noteVibrato", "chCompress", "chLevelRide", "chPeak", "chEchoDuck", "chBoomTame", "chHarshTame", "chReverb", "drift"].includes(id)) return Math.round(v * 100) + "%";
  if (id === "cleanSens") return Math.round(v) + "%";
