$("guideBtn").onclick = () => { $("detailSheet").hidden=true; $("guideSheet").hidden = !$("guideSheet").hidden; syncGuide(); };
$("guideClose").onclick = () => { $("guideSheet").hidden = true; endLoop(); };
$("guideOn").onchange = () => { S.guidePrefs.enabled = $("guideOn").checked; endLoop(); pushGuidePrefs(); };
