    $("tipReason").textContent = S.guidePrefs.enabled && S.st && S.st.rendered && !S.dirty ? "Nothing the guide checks needs attention (or you chose Not now / Keep my choice). That's not a guarantee of a perfect vocal: always listen with your beat." : "The guide listens to your recorded vocal after processing settles. It never changes a knob until you tap Apply.";
