async function phraseAddAudio(p,channels,rate,origin,name){const w=phraseWorkspace();if(!w.phrases.includes(p))throw new Error('That phrase no longer exists.');if(p.takes.length>=32)throw new Error('This phrase has 32 attempts. Save the project and remove unused attempts first.');const converted=await phraseResample(channels,rate,w.rate),t={id:'t'+w.nextId++,name:name||phraseNextTakeName(p),rate:w.rate,channels:converted,origin,offsetMs:0,gainDb:0,profile:null};const trial={...w,phrases:w.phrases.map(q=>q===p?{...p,takes:[...p.takes,t]}:q)};PhraseCore.validate(trial);phraseBackup();p.takes.push(t);phraseNoteTakeName(p,t);clearedSession=null;phraseChanged(t.name+' added — '+p.takes.length+' attempt'+(p.takes.length===1?'':'s')+'. Listen, then tap Choose.');phraseAnalyze(t,p);}
function phraseRecordOptions(){const p=selectedPhrase(),w=phraseWorkspace();if(!p)throw new Error('Add a phrase first.');if(p.takes.length>=32||w.phrases.reduce((n,p)=>n+p.takes.length,0)>=128)throw new Error('Save the project and remove unused takes before recording more.');const captured=w.phrases.reduce((n,p)=>n+p.takes.reduce((n,t)=>n+t.channels[0].length/w.rate,0),0);const bytes=(w.base?w.base.channels.reduce((n,c)=>n+c.byteLength,0):0)+w.phrases.reduce((n,p)=>n+p.takes.reduce((n,t)=>n+t.channels.reduce((n,c)=>n+c.byteLength,0),0),0);if(bytes+(p.end-p.start+w.lead+.8)*w.rate*8>PhraseCore.MAX_BYTES)throw new Error('Save the project and remove unused attempts before recording more; this phone workspace is near its 128 MB audio limit.');if(captured+p.end-p.start+w.lead+.8>PhraseCore.MAX_TOTAL)throw new Error('The project is near its 30-minute take limit. Save and remove unused takes first.');return {p,w,start:p.start-w.lead-.15,end:p.end+.3};}
function phraseScheduleRecording(r,ctx){const o=r.phrase;r.origin=o.start;r.nodes=[];r.monitorSources=[];r.clockStart=ctx.currentTime;const schedule=(buffer,gain,from,to)=>{from=Math.max(0,from);to=Math.min(to,buffer.duration);if(to<=from)return;const s=ctx.createBufferSource(),g=ctx.createGain();s.buffer=buffer;g.gain.value=gain;s.connect(g).connect(ctx.destination);s.start(r.clockStart+from-o.start,from,to-from);r.monitorSources.push(s);r.nodes.push(g);return g;};const bg=1,vg=typeof pvsRecVocalGain==='function'?pvsRecVocalGain():1;if(S.beat&&$('beatOn').checked&&bg>0)r.beatGain=schedule(S.beat,S.beatLevel*bg,o.start,o.free?Infinity:o.end);if(vg>0){const channels=PhraseCore.compose(o.w);const b=bufferOf(channels,o.w.rate);const gain=phraseSafeGain(channels)*vg;schedule(b,gain,o.start,o.p.start);if(!o.free)schedule(b,gain,o.p.end,o.end);}$('phraseRecNote').textContent='Headphones: '+(r.beatGain?'backing':'no backing')+(vg>0?' + existing vocal outside this phrase':' · old vocal off')+'. Microphone: new attempt only.';if(typeof pvsRecScheduled==='function')pvsRecScheduled(r,ctx);r.limit=setTimeout(()=>{if(rec===r&&r.mr.state!=='inactive'){r.autoStop=o.free?'cap':'end';r.mr.stop();}},(o.free?o.cap:(o.end-o.start))*1000);}
async function phraseFinishRecording(r,channels,rate){const ctx=audioCtx(),latency=typeof pvsLatency==='function'?pvsLatency():Math.max(0,(ctx.outputLatency||0)+(ctx.baseLatency||0));await phraseAddAudio(r.phrase.p,channels,rate,r.origin-latency,phraseNextTakeName(r.phrase.p));const t=r.phrase.p.takes.at(-1);if(!PhraseCore.covers(t,r.phrase.p))phraseMessage('Recording kept, but it ended before the phrase was complete. Adjust End or redo this section.');else if(r.clip)phraseMessage('Recording kept. Some input peaks were loud; check the clipping analysis before choosing.');showPage('record');}
async function phraseApply(){if(phraseBusy())return false;const w=phraseWorkspace();if(!w.base&&w.applied<0&&!w.phrases.some(p=>p.selected)){phraseMessage('Choose at least one take before applying your assembled vocal.');return false;}S.phraseWorking=true;syncPhraseUI();try{const pcm=PhraseCore.compose(w),last=sessionSnapshot()||{};S.phraseApplying=true;if(S.main)await restoreSession({...last,v:5,name:w.title||'Assembled vocal',rate:w.rate,pcm,takes:[],notes:[],edits:{breaths:[],timing:[],comp:[]},phrases:w});else await openVocal(pcm,w.rate,w.title||'Assembled vocal',false);S.phrases=w;w.applied=w.revision;w.appliedSig=phraseCompSig(w);w.appliedDur=PhraseCore.duration(w);S.loadedNotice='Assembled vocal loaded — '+w.phrases.filter(p=>p.selected).length+' chosen phrases.';persist();phraseMessage('Assembled vocal applied. Use Clean, Tune and Chain, then Save.');return true;}catch(e){phraseMessage('Could not apply: '+e.message);return false;}finally{S.phraseApplying=false;S.phraseWorking=false;syncPhraseUI();renderOpen();}}
function phraseSnapshot(last){const w=S.phrases;if(!last&&!w?.phrases.length&&!S.song&&!S.beat&&!S.recoveryFiles?.length)return null;const result={...(last||{name:w?.title||'Recording session',rate:w?.rate||S.rate,pcm:null,P:{...S.P}}),v:5,song:S.song?SongCore.clone(S.song):null,recordBacking:$('beatOn').checked,phrases:w?PhraseCore.clone(w):null,recoveryFiles:(S.recoveryFiles||[]).slice()};if(!last){const g=S.guide||{};result.guide={...S.guidePrefs,locked:[...(g.locked||[])],dismissed:{...(g.dismissed||{})}};result.mix={...S.mix};}/* 0.18.3 (review 03): tempo and the other song settings are kept without a whole vocal too */if(result.phrases)for(const p of result.phrases.phrases)for(const t of p.takes)delete t.analysisToken;result.backing=S.beat?{name:S.beatName,rate:S.beat.sampleRate,channels:Array.from({length:S.beat.numberOfChannels},(_,i)=>S.beat.getChannelData(i)),level:S.beatLevel,on:$('beatOn').checked}:null;return result;}
function phraseRestoreData(last){if(last.phrases){PhraseCore.validate(last.phrases);if(!S.phraseApplying)for(const p of last.phrases.phrases)for(const t of p.takes){delete t.analysisToken;t.profile=null;t.analysisError=null;}}if(last.backing)PhraseCore.audio(last.backing);S.phrases=last.phrases||null;if(Array.isArray(last.recoveryFiles))S.recoveryFiles=last.recoveryFiles.slice();phraseHistoryReset();if(Object.prototype.hasOwnProperty.call(last,'backing')){S.beat=last.backing?bufferOf(last.backing.channels,last.backing.rate):null;S.beatName=last.backing?.name||'';S.beatLevel=last.backing?.level??.8;$('beatOn').checked=last.backing?.on!==false;$('beatLevel').value=S.beatLevel*100;$('beatLevelText').textContent=Math.round(S.beatLevel*100)+'%';S.fitBeat=null;sendBeat();}if(typeof last.recordBacking==='boolean')$('beatOn').checked=last.recordBacking;if(!S.songApplying){if(window.SongStudio)SongStudio.restore(last);else S.song=last.song?SongCore.clone(last.song):null;}phraseAnalyzeMissing();syncPhraseUI();}
async function phraseProjectPack(root,files){const snap=phraseSnapshot(null);if(!snap)return;const audio=(a,file)=>{files.push({name:file,data:wavFloat(a.channels,a.rate)});const meta={...a,file};delete meta.channels;return meta;};const w=snap.phrases;if(w){root.phoneRecording={...w,base:w.base?audio(w.base,'pbv-recording-base.wav'):null,phrases:w.phrases.map((p,i)=>({...p,takes:p.takes.map((t,j)=>{const a=audio(t,'pbv-phrase-'+i+'-take-'+j+'.wav');delete a.analysisToken;return a;})}))};}root.phoneRecordBacking=snap.recordBacking;if(snap.backing)root.phoneBacking=audio(snap.backing,'pbv-recording-backing.wav');if(window.Recovery)await Recovery.pack(root,files);if(window.SongStudio)await SongStudio.pack(root,files);}
async function phraseProjectUnpack(root,files){const audio=async a=>{const f=files.get(baseName(a.file).toLowerCase());if(!f)throw new Error('Project recording audio is missing: '+a.file);const decoded=await decodeBytes(f.data,a.file);return {...a,channels:decoded.channels,rate:decoded.rate};};let w=null;if(root.phoneRecording){w=structuredClone(root.phoneRecording);w.base=w.base?await audio(w.base):null;for(const p of w.phrases)for(let i=0;i<p.takes.length;i++){p.takes[i]=await audio(p.takes[i]);delete p.takes[i].analysisToken;}PhraseCore.validate(w);}const backing=root.phoneBacking?await audio(root.phoneBacking):null;if(backing)PhraseCore.audio(backing);return {song:window.SongStudio?await SongStudio.unpack(root,files):null,phrases:w,backing,recordBacking:typeof root.phoneRecordBacking==='boolean'?root.phoneRecordBacking:backing?.on,recoveryFiles:window.Recovery?Recovery.unpack(root,files):[]};}
function phraseDraw(){const c=$('phraseTimeline'),ctx=c.getContext('2d');if(!ctx)return;const w=phraseWorkspace(),width=c.clientWidth||320,h=130,ratio=Math.min(2,window.devicePixelRatio||1);c.width=width*ratio;c.height=h*ratio;ctx.scale(ratio,ratio);ctx.fillStyle='#10181d';ctx.fillRect(0,0,width,h);const duration=Math.max(PhraseCore.duration(w),S.beat?.duration||0,8),x=t=>t/duration*width;ctx.fillStyle='#9daaaa';ctx.font='12px sans-serif';ctx.fillText('BACKING',8,16);if(S.beat){const a=S.beat.getChannelData(0);ctx.fillStyle='#4a636e';for(let i=0;i<width;i++){const from=Math.floor(i/width*a.length),to=Math.floor((i+1)/width*a.length);let peak=0;for(let j=from;j<to;j+=Math.max(1,Math.floor((to-from)/20)))peak=Math.max(peak,Math.abs(a[j]));ctx.fillRect(i,35-peak*14,1,Math.max(1,peak*28));}}ctx.fillStyle='#9daaaa';ctx.fillText('VOCAL PHRASES',8,68);for(const p of w.phrases){ctx.fillStyle=p.selected?'#68c2aa':'#786846';ctx.fillRect(x(p.start),78,Math.max(2,x(p.end-p.start)),24);if(p.id===w.selected){ctx.strokeStyle='#fff';ctx.strokeRect(x(p.start),77,Math.max(2,x(p.end-p.start)),26);}}ctx.strokeStyle='#f5d08a';ctx.beginPath();ctx.moveTo(x(w.cursor),0);ctx.lineTo(x(w.cursor),h);ctx.stroke();ctx.fillStyle='#dce4df';ctx.fillText(fmtShort(duration),Math.max(0,width-50),122);}
function syncPhraseUI(){if(!phraseReady)return;const w=phraseWorkspace(),p=selectedPhrase(),locked=phraseBusy();const set=(id,v)=>{if(document.activeElement!==$(id))$(id).value=v;};set('phraseTitle',w.title);set('phraseLead',w.lead);set('phraseFade',w.fadeMs);set('phraseCursor',w.cursor);$('phraseCursor').max=Math.min(899.5,Math.max(8,PhraseCore.duration(w),S.beat?.duration||0));$('phraseCursorText').textContent=fmt(w.cursor);$('phraseBaseInfo').textContent=w.base?'Starting vocal: '+w.base.name+' · kept outside replaced phrases.':S.main&&!w.phrases.length?'Current vocal will be kept outside your new phrases.':'Build your vocal one phrase at a time. No original vocal is overwritten.';$('phraseBackingInfo').textContent=S.beat?'BACKING: '+S.beatName+' · '+($('beatOn').checked?'plays in headphones':'muted — enable on Open tab'):'BACKING: none loaded. You can record without one.';$('phraseList').innerHTML=w.phrases.map(q=>'<button class="btn '+(q.id===w.selected?'on':'')+'" data-phrase="'+phraseEsc(q.id)+'">'+phraseEsc(q.name)+' · '+fmt(q.start)+'–'+fmt(q.end)+' · '+q.takes.length+' takes'+(q.selected?' ✓':'')+'</button>').join('')||'<p class="hint">Set a start and end below, then Add phrase.</p>';
  for(const b of $('phraseList').querySelectorAll('[data-phrase]')){b.disabled=locked;b.onclick=()=>phraseSelect(b.dataset.phrase);}if(p){set('phraseLabel',p.name);set('phraseStart',p.start);set('phraseEnd',p.end);}set('phraseKey',w.key||0);set('phraseScale',w.scale||0);$('phraseReference').innerHTML='<option value="">Key only (no melody reference)</option>'+(p?p.takes.map(t=>'<option value="'+phraseEsc(t.id)+'">'+phraseEsc(t.name)+'</option>').join(''):'');$('phraseReference').value=p?.reference||'';
  const rank=p?PhraseCore.rank(p,w.key||0,w.scale||0):{rows:[],winner:null};$('phraseRecommendation').textContent=!p?'Add a phrase to compare attempts.':p.takes.length<2?'Record at least two attempts for a comparison.':rank.winner?'Suggested: '+p.takes.find(t=>t.id===rank.winner).name+'. Check the measurements and listen before choosing.':rank.tied?'These takes are close. Listen and choose the delivery you prefer.':p.takes.some(t=>t.analysisToken)?'Analysing raw takes. You can listen or choose while analysis finishes.':'No reliable winner yet. Check incomplete coverage, quiet audio or uncertain pitch.';
  const takesHTML=p?p.takes.map(t=>{const r=rank.rows.find(r=>r.id===t.id),a=t.profile;const metrics=a?'Stable pitch: '+(r.pitch===null?'uncertain':Math.round(r.pitch)+' cents from '+(r.melody?'reference':'nearest scale note'))+' · clipped samples: '+a.clippedPercent.toFixed(2)+'% · vocal/background: '+(a.contrast===null?'no lead-in measurement':a.contrast.toFixed(1)+' dB')+(r.timing!==null?' · onset difference: '+Math.round(r.timing)+' ms':''):'Analysis: '+(t.analysisError||'waiting…');return '<article class="phrase-take '+(p.selected===t.id?'chosen ':'')+(rank.winner===t.id?'suggested':'')+'" data-take="'+t.id+'"><div class="takehead"><input class="takename" type="text" maxlength="60" value="'+phraseEsc(t.name)+'" data-rename="'+t.id+'" aria-label="Take name"><strong>'+(p.selected===t.id?' CHOSEN':'')+(rank.winner===t.id?' · SUGGESTED':'')+'</strong><span class="stars" role="group" aria-label="Rating">'+[1,2,3,4,5].map(i=>'<button class="star'+(i<=(t.rating||0)?' on':'')+'" data-rate="'+i+'" data-id="'+t.id+'" aria-label="'+i+' star'+(i>1?'s':'')+'">★</button>').join('')+'</span></div><p class="hint">'+phraseEsc(metrics)+'</p>'+(!PhraseCore.covers(t,p)?'<p class="hint">Incomplete coverage. Shorten the phrase or redo it.</p>':'')+'<div class="btnrow"><button class="btn" data-action="listen" data-id="'+t.id+'">Listen</button><button class="btn primary" data-action="choose" data-id="'+t.id+'">'+(p.selected===t.id?'Chosen':'Choose')+'</button><button class="btn" data-action="retry" data-id="'+t.id+'">Analyse again</button><button class="btn" data-action="remove" data-id="'+t.id+'">Remove</button></div><div class="selrow"><label>Alignment (ms)<input type="number" min="-500" max="500" step="10" value="'+t.offsetMs+'" data-field="offsetMs" data-id="'+t.id+'"></label><label>Assembly level (dB)<input type="number" min="-12" max="12" step="0.5" value="'+t.gainDb+'" data-field="gainDb" data-id="'+t.id+'"></label></div></article>';}).join(''):'';
  if(!$('phraseTakes').contains(document.activeElement)&&$('phraseTakes').innerHTML!==takesHTML)$('phraseTakes').innerHTML=takesHTML;
  for(const b of $('phraseTakes').querySelectorAll('[data-action]')){b.disabled=locked;b.onclick=()=>{const id=b.dataset.id;({listen:phraseListen,choose:phraseChoose,remove:phraseRemoveTake,retry:id=>{const t=p.takes.find(t=>t.id===id);if(t){phraseAnalyze(t,p);syncPhraseUI();}}})[b.dataset.action](id);};}for(const input of $('phraseTakes').querySelectorAll('[data-field]')){input.disabled=locked;input.onchange=()=>phraseAdjust(input.dataset.id,input.dataset.field,+input.value);}
  for(const id of ['phraseTitle','phraseLead','phraseFade','phraseCursor','phraseContinue','phraseAtPlayhead','phraseNew','phraseStart','phraseEnd','phraseLabel','phraseBacking','phraseKey','phraseScale','phraseReference','phraseCompareBeat'])$(id).disabled=locked;
  for(const id of ['phraseBounds','phraseImport','phraseRemove','phraseUnchoose'])$(id).disabled=locked||!p;$('phraseUndo').hidden=!phraseUndo;$('phraseUndo').disabled=locked||!phraseUndo;$('phraseRecord').disabled=!!S.micBlocked||(!rec&&(locked||!p))||!!(rec&&rec.target!=='phrase');$('phraseStop').textContent=rec?.target==='phrase'?'Stop and keep attempt':'Stop playback';$('phraseRecover').hidden=!S.phraseRecovery;$('phraseRecordLabel').textContent=rec?.target==='phrase'?'Stop and keep attempt':p?.takes.length?'Redo this section':'Record this phrase';$('phraseApply').disabled=locked||(!w.base&&w.applied<0&&!w.phrases.some(p=>p.selected));$('phraseSave').disabled=canSaveProject()!==true;$('phraseSave').title=canSaveProject(true)===true?'Back up project (.zip with every take)':canSaveProject(true);$('phraseListenSong').disabled=locked||!w.base&&!w.phrases.some(p=>p.selected);$('phraseAssemblyInfo').textContent=w.phrases.filter(p=>p.selected).length+' of '+w.phrases.length+' phrases chosen. '+(w.applied===w.revision?'Sent to POLISH.':'Press Comp done (or Load my new comp in POLISH) to send this comp to POLISH.');phraseDraw();}
function phraseBind(){phraseReady=true;$('phraseTimeline').addEventListener('pointerdown',e=>{if(phraseBusy())return;const r=$('phraseTimeline').getBoundingClientRect(),w=phraseWorkspace(),duration=Math.max(PhraseCore.duration(w),S.beat?.duration||0,8);w.cursor=Math.max(0,Math.min(899.5,(e.clientX-r.left)/r.width*duration));syncPhraseUI();persist();});for(const [id,values] of [['phraseKey',KEYS],['phraseScale',SCALES]])$(id).innerHTML=values.map((s,i)=>'<option value="'+i+'">'+s+'</option>').join('');/* 0.17.0: the Session window's Record button is now 'Go to 1 RECORD & COMP' (data-act=toRC) */$('phraseBacking').onclick=()=>$('fileBeat').click();$('phraseNew').onclick=()=>phraseNew();$('phraseContinue').onclick=()=>{if(!phraseBusy()){$('phraseLabel').value='';phraseNew(phraseWorkspace().cursor);}};$('phraseAtPlayhead').onclick=()=>{if(!phraseBusy()){$('phraseLabel').value='';phraseNew(Math.min(899.5,Math.max(0,currentPos()+(loop?.phrase?loop.beatOffset||0:0))));}};$('phraseBounds').onclick=()=>{if(phraseBusy())return;const p=selectedPhrase();if(!p)return;try{const start=+$('phraseStart').value,end=+$('phraseEnd').value;PhraseCore.span(start,end);phraseBackup();Object.assign(p,{start,end,name:$('phraseLabel').value.trim()||p.name});for(const t of p.takes)phraseAnalyze(t,p);if(p.selected&&!PhraseCore.covers(p.takes.find(t=>t.id===p.selected),p))p.selected=null;phraseChanged('Phrase boundaries updated. Check each take before choosing.');}catch(e){phraseMessage(e.message);}};$('phraseUnchoose').onclick=phraseUnchoose;$('phraseRemove').onclick=()=>{if(phraseBusy())return;const rp=selectedPhrase();if(!rp)return;if(!confirm('Remove phrase “'+rp.name+'” and its '+rp.takes.length+' take'+(rp.takes.length===1?'':'s')+'?\n\nUndo (Ctrl+Z) can bring it back.'))return;phraseBackup();const w=phraseWorkspace();w.phrases=w.phrases.filter(p=>p.id!==w.selected);w.selected=w.phrases.at(-1)?.id||null;phraseChanged('Phrase removed. Undo restores its attempts.');};$('phraseUndo').onclick=()=>phraseHistory(-1);$('phraseRedo').onclick=()=>phraseHistory(1);$('phraseRecord').onclick=()=>{if(rec?.target==='phrase'){if(rec.mr.state!=='inactive')rec.mr.stop();return;}try{const options=phraseRecordOptions();startRecording('phrase',options);}catch(e){phraseMessage(e.message);}};$('phraseImport').onclick=()=>$('phraseFile').click();$('phraseFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f||phraseBusy())return;const p=selectedPhrase();if(!p)return;S.phraseWorking=true;syncPhraseUI();try{const b=await decodeFile(f);if(b.duration>70)throw new Error('Import one phrase attempt under 70 seconds. Use Open for a whole song.');await phraseAddAudio(p,toChannels(b),b.sampleRate,p.start,f.name);}catch(e){phraseMessage('Attempt not added: '+e.message);}finally{S.phraseWorking=false;syncPhraseUI();}};$('phraseListenSong').onclick=()=>phraseListen();$('phraseRecover').onclick=async()=>{const b=S.phraseRecovery;if(!b)return;try{const ext=/mp4|m4a/.test(b.type)?'m4a':/wav/.test(b.type)?'wav':/ogg/.test(b.type)?'ogg':'webm';await saveDownload('Recovered microphone attempt.'+ext,b);phraseMessage('Microphone file saved. You can import it again for this phrase.');}catch(e){phraseMessage('Recovery download failed: '+e.message);}};$('phraseStop').onclick=()=>{if(rec?.target==='phrase'){if(rec.mr.state!=='inactive')rec.mr.stop();}else{endLoop();stopPlayback();phraseMessage('Stopped.');}};$('phraseApply').onclick=phraseApply;$('phraseSave').onclick=async()=>{await saveProject();$('phraseSaveStatus').textContent=$('saveStatus').textContent;};$('phraseTitle').onchange=()=>{phraseWorkspace().title=$('phraseTitle').value.trim().slice(0,120)||'My phrase recording';phraseChanged();};for(const [id,field,min,max] of [['phraseLead','lead',0,5],['phraseFade','fadeMs',0,100]])$(id).onchange=()=>{const v=+$(id).value;if(!Number.isFinite(v))return;phraseBackup();phraseWorkspace()[field]=Math.max(min,Math.min(max,v));phraseChanged();};$('phraseCursor').oninput=()=>{phraseWorkspace().cursor=+$('phraseCursor').value;$('phraseCursorText').textContent=fmt(phraseWorkspace().cursor);phraseDraw();persist();};for(const [id,field] of [['phraseKey','key'],['phraseScale','scale']])$(id).onchange=()=>{phraseWorkspace()[field]=+$(id).value;syncPhraseUI();persist();};$('phraseReference').onchange=()=>{const p=selectedPhrase();if(p){p.reference=$('phraseReference').value||null;syncPhraseUI();persist();}};window.addEventListener('resize',()=>{if(!$('page-record').hidden)phraseDraw();});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){if(rec?.target==='phrase'&&rec.mr.state!=='inactive')rec.mr.stop();cancelPersist();const snapshot=sessionSnapshot();if(snapshot)writeRemembered(snapshot).catch(e=>{$('phraseSaveStatus').textContent='Browser save failed. Download a song project: '+e.message;});}});syncPhraseUI();}
